    /// The rung to play next: down one when downloads fall behind playback, up one when far ahead.
    pub fn next_rung(&self, rung: usize, rungs: usize, download_bps: f64, bitrate_bps: f64) -> usize {
        if download_bps < bitrate_bps * 1.1 && rung > 0 { rung - 1 }
        else if self.ahead_secs > self.target_secs && download_bps > bitrate_bps * 1.5 && rung + 1 < rungs { rung + 1 }
        else { rung }
